int solve(vector<int>& cost, int idx) {
    if (idx >= (int)cost.size()) return 0;
    int n = cost.size();
    vector<int> dp(n + 2, 0);
    for (int i = n - 1; i >= idx; --i) {
        dp[i] = cost[i] + min(dp[i + 1], dp[i + 2]);
    }
    return dp[idx];
}

