int maximumTip(vector<int>& arr1, vector<int>& arr2, int n, int x, int y) {
    if (n <= 0) return 0;
    // memo table sized from the arguments, no fixed constants
    vector<vector<vector<int>>> memo(n + 1, vector<vector<int>>(x + 1, vector<int>(y + 1, INT_MIN)));
    function<int(int,int,int)> solve = [&](int i, int a, int b) -> int {
        if (i == 0) return 0;
        int &res = memo[i][a][b];
        if (res != INT_MIN) return res;
        if (a != 0 && b != 0) {
            int take1 = arr1[i - 1] + solve(i - 1, a - 1, b);
            int take2 = arr2[i - 1] + solve(i - 1, a, b - 1);
            res = max(take1, take2);
        } else if (b == 0) {
