int calculate(int pos,int left,int k,int L,int R) {
    if (pos > k) return 0;
    int steps = k - pos;
    if (steps < 0 || left < 0) return 0;
    long long minSum = 1LL * steps * L;
    long long maxSum = 1LL * steps * R;
    if (left < minSum || left > maxSum) return 0;
    vector<vector<int>> dp(steps + 1, vector<int>(left + 1, 0));
    dp[0][0] = 1;
    for (int s = 1; s <= steps; ++s) {
