const int MAX=INT_MAX;
int minOperation(string& s,int i,int j,int count) {
    int n = (int)s.size();
    const int INF = INT_MAX/2;
    vector<vector<int>> memo(n+1, vector<int>(n+1, -1));
    function<int(int,int)> dfs = [&](int ii, int jj) -> int {
        if (ii >= n && jj < 0) return INF;
        if (ii == jj) return INF;
        if (ii >= n) return 1 + dfs(ii, jj-1);
        if (jj < 0) return 1 + dfs(ii+1, jj);
        int idxj = jj + 1;
        if (memo[ii][idxj] != -1) return memo[ii][idxj];
        if (s[ii] == s[jj]) {
            memo[ii][idxj] = 0;
        } else {
            int a = dfs(ii, jj-1);
            int b = dfs(ii+1, jj);
            int best = min(a,b);
            memo[ii][idxj] = (best >= INF ? INF : 1 + best);
        }
        return memo[ii][idxj];
    };
    int add = dfs(i, j);
    if (add >= INF) return MAX;
    return count + add;
}

