long long CountSubset(int*arr,int n) {
    long long ans=powmod(2,n-1);
    sort(arr,arr+n);
    for(int i=0;i<n;++ i) {
        int j=i+1;
        while(j<n&&arr[j]== arr[i]) {
            int r=n-1-j;
            int l=i;
            ans =(ans+nCr(l+r,l))%mod;
            j++;
        }
    }
    return ans;
}

