using namespace std;
int printCountRec(int dist) {
    if (dist < 0) return 0;
    if (dist == 0) return 1;
    vector<int> dp(dist + 1);
    dp[0] = 1;
    for (int i = 1; i <= dist; ++i) {
        int v1 = (i - 1 >= 0) ? dp[i - 1] : 0;
        int v2 = (i - 2 >= 0) ? dp[i - 2] : 0;
        int v3 = (i - 3 >= 0) ? dp[i - 3] : 0;
        dp[i] = v1 + v2 + v3;
    }
    return dp[dist];
}

